const countByType = <T extends { type: string } | { itemType: string }>(
  entries: T[],
  key: "type" | "itemType"
): Record<string, number> => {
  const counts: Record<string, number> = {};
  for (const entry of entries) {
    const type = (entry as any)[key];
    counts[type] = (counts[type] ?? 0) + 1;
  }
  return counts;
};
```

